<?php $page_title='Messages'; require_once 'includes/header.php'; require_login();
$me=user()['id'];$to=(int)($_GET['user']??0);
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$action=$_POST['action']??'';if($action==='send'){ $rid=(int)$_POST['receiver_id'];$body=trim($_POST['body']??'');if($rid && $body){$pdo->prepare('INSERT INTO messages(sender_id,receiver_id,body) VALUES(?,?,?)')->execute([$me,$rid,$body]);notify_user($rid,'New FIBIN message','You received a new message.','messages.php?user='.$me);}redirect('messages.php?user='.$rid);} }
$people=$pdo->query("SELECT id,name,username,avatar,role,last_seen FROM users WHERE id<>".(int)$me." ORDER BY name LIMIT 80")->fetchAll();
if(!$to && $people)$to=(int)$people[0]['id'];$target=null;if($to){$s=$pdo->prepare('SELECT id,name,username,avatar,role FROM users WHERE id=?');$s->execute([$to]);$target=$s->fetch();}
$chat=[];if($target){$s=$pdo->prepare('SELECT m.*,u.name sender_name,u.avatar sender_avatar FROM messages m JOIN users u ON u.id=m.sender_id WHERE (sender_id=? AND receiver_id=?) OR (sender_id=? AND receiver_id=?) ORDER BY m.created_at ASC');$s->execute([$me,$to,$to,$me]);$chat=$s->fetchAll();$pdo->prepare('UPDATE messages SET is_read=1 WHERE receiver_id=? AND sender_id=?')->execute([$me,$to]);}
?><section class="page-hero compact"><span class="kicker">PRIVATE COMMUNICATION</span><h1>Messages & video calls</h1><p>Chat with donors, receivers and FIBIN admins. Start a video meeting whenever you need to coordinate a pickup.</p></section><div class="messenger"><aside class="people-list"><div class="search-mini">FIBIN people</div><?php foreach($people as $p):?><a class="person <?=($to==$p['id']?'active':'')?>" href="messages.php?user=<?=$p['id']?>"><span class="avatar-sm"><?php if($p['avatar']):?><img src="<?=e($p['avatar'])?>"><?php else:?><?=e(strtoupper(substr($p['name'],0,1)))?><?php endif;?></span><span><b><?=e($p['name'])?></b><small>@<?=e($p['username'])?> · <?=e($p['role'])?></small></span></a><?php endforeach;?></aside><section class="chat-panel"><?php if($target):?><div class="chat-head"><div><b><?=e($target['name'])?></b><small>@<?=e($target['username'])?> · <?=e($target['role'])?></small></div><a class="btn ghost" target="_blank" href="https://meet.jit.si/FIBIN-<?=rawurlencode($me.'-'.$to)?>">📹 Video call</a></div><div class="chat-body" id="chatBody"><?php foreach($chat as $m):?><div class="bubble <?=($m['sender_id']==$me?'mine':'')?>"><div><?=nl2br(e($m['body']))?></div><small><?=e(time_ago($m['created_at']))?></small></div><?php endforeach;?></div><form method="post" class="chat-compose"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><input type="hidden" name="action" value="send"><input type="hidden" name="receiver_id" value="<?=$to?>"><input name="body" required placeholder="Write a message…"><button class="btn primary">Send</button></form><?php else:?><div class="empty-state"><h2>No conversation selected</h2><p>Select a community member to start chatting.</p></div><?php endif;?></section></div><?php require_once 'includes/footer.php'; ?>
